    L2 = 5,
    R1 = 6,
    R2 = 7,
    TRIANGLE = 8,
    CROSS = 9,
    SQUARE = 10,
    CIRCLE = 11,
    UP = 12,
    DOWN = 13,
    LEFT = 14,
    RIGHT = 15,
    SELECT = 16,
    START = 17,
