// Function to send one discrete controller event (index and value)
fn sendControllerEvent(sock: posix.fd_t, addr: *const net.Address, index: i32, value: i32) !void {
    // We must ensure the data is packed as two standard integers (4 bytes each)
    var packet: [8]u8 = undefined;

    // Pack index (4 bytes)
    std.mem.writeInt(u32, &packet[0..4], index);
    // Pack value (4 bytes)
    std.mem.writeInt(u32, &packet[4..8], value);

    const sockaddr = &addr.any;
    const addrlen = addr.getOsSockLen();
    const bytesToSend = packet[0..8];
    const totalBytes = bytesToSend.len;

